// Declarações de tipo dos mods do MineClaude (autocompletar no editor). O texto do comportamento: docs/guia-de-mods.md.
// GERADO a partir do jogo por `bun run sdk:sync`: não edite à mão.
//
// Use in a mod (JavaScript):
//   // @ts-check
//   /** @param {import('./mineclaude-mod').ModContext} ctx */
//   export default function register(ctx) { ... }
//
// Entrypoints (mod.json): "main": "main.js" (shorthand) or "entrypoints": { "main": [...], "server": [...], "client": [...] }.
// Every file default-exports register(ctx) and gets the same ctx: main files run on both sides (content goes there
// only), server files only on the server (ServerModContext; never served to the browser, nor anything in server/),
// client files only in the browser page (ClientModContext).

/** Nome completo `mod:nome` (`[a-z0-9_]+:[a-z0-9_]+`), ex.: `meumod:rubi`, `mineclaude:stone`. */
export type FullName = `${string}:${string}`;
/** Nome de item/bloco: completo (`mod:nome`) ou, na API, o nome curto de um item/bloco base (`stone`).
 * Os nomes base aparecem no autocompletar (`BaseItemName`); qualquer outro texto continua aceito. */
export type ItemName = BaseItemName | FullName | (string & {});
