  /** Troca uma estadia pela sua. Em cadeia: a forma função recebe `previous`, os ganchos do que estava antes. Dois mods no mesmo alvo geram aviso. */
  replace(name: FullName, stay: StayType | ((previous: Readonly<Partial<StayType>>) => StayType), opts?: ChainOptions): void;
  /** Embrulha ganchos da estadia de qualquer mod; `previous` é o ÚLTIMO argumento (`previous()` repete os recebidos; não chamar troca o gancho). */
