// ---------------------------------------------------------------- salas e minigames (ctx.rooms)

/** Um bloco do mapa de uma sala: `block` é o nome (`'snow'` vale `'mineclaude:snow'`). */
export interface RoomCell { x: number; y: number; z: number; block: string }
/** Lista de blocos: `[{ x, y, z, block }, ...]` ou plana, `[x, y, z, 'block', x, y, z, 'block', ...]` (mais barata para arenas grandes). */
export type RoomCells = RoomCell[] | Array<number | string>;
/** O pedaço do mundo que a sala pode tocar: uma caixa (a arena e a folga em volta). Escrever fora dela lança. */
export interface RoomWorld {
  readonly box: { readonly x0: number; readonly x1: number; readonly y0: number; readonly y1: number; readonly z0: number; readonly z1: number };
  contains(x: number, y: number, z: number): boolean;
  /** O nome completo do bloco, ou `null` fora da caixa. */
  getBlock(x: number, y: number, z: number): string | null;
  /** O que o motor sabe da célula (para planejar em volta dela: uma explosão que poupa o esqueleto, uma jaula sobre laje), ou `null` fora da caixa. */
  info(x: number, y: number, z: number): { readonly name: string; readonly air: boolean; readonly solid: boolean; readonly liquid: boolean; readonly unbreakable: boolean; readonly container: boolean; /** Altura do topo do bloco (1 = cheio). */ readonly top: number; /** `blastResistance` do bloco (0 = não resiste). */ readonly blastResistance: number } | null;
  /**
   * O CHUNK desta célula tem alguma edição salva? A sala cujo mapa não é construído uma vez, mas escrito e apagado
   * enquanto se joga (um lote por jogador: o Magnata), pergunta isso no boot antes de tocar em nada: ler uma célula de
   * um chunk que ninguém nunca editou o GERARIA, e uma sala com dezenas de áreas geraria dezenas deles por nada.
   */
  edited(x: number, y: number, z: number): boolean;
  /** O texto da placa nesta célula, ou `null`. */
  getSign(x: number, y: number, z: number): string | null;
  /**
   * Escreve o texto da placa nesta célula (a célula tem de ter uma placa: a sala a pôs ali), até 48 caracteres.
   * O mesmo texto de novo não muda nada e `null` esquece o texto; devolve se mudou. A sala cujas placas são a TELA
   * dela (as placas de preço de um lote do Magnata) as reescreve a cada compra.
   */
  setSign(x: number, y: number, z: number, text: string | null): boolean;
  setBlock(x: number, y: number, z: number, block: string): number;
  /** Devolve quantas células mudaram; quem está perto recebe as mudanças. */
  setBlocks(list: RoomCells): number;
  /** Preenche o paralelepípedo entre dois cantos. */
  fill(a: Pos, b: Pos, block: string): number;
}
export interface RoomTeam { readonly index: number; readonly name: string; readonly color: string; /** Quem do time está de pé. */ readonly players: PlayerApi[]; /** Todos do time, também quem já foi eliminado (vencem junto: `room.win(team.members)`). */ readonly members: PlayerApi[] }
/** Preço ou entrega da loja: o par `[item, quantidade]` (lista solta para o JS puro não precisar de cast; `'iron_ingot'` vale `'mineclaude:iron_ingot'`). */
export type ShopStack = ReadonlyArray<string | number>;
/** Uma oferta da loja da partida: paga `price`, recebe `give` (tudo ou nada). `key` é o que se digita depois do comando (`/comprar pao`). */
export interface RoomShopOffer { key: string; name: string; price: ShopStack; give: ShopStack[]; /** Item desenhado na linha (padrão: o primeiro de `give`). */ icon?: string }
/** Uma melhoria do TIME de quem compra: `prices[n]` é o preço do nível n+1; vale até o fim da partida. `max` é o que o comando diz no último nível. */
export interface RoomShopUpgrade { key: string; name: string; icon: string; prices: ShopStack[]; desc?: string; max?: string }
/**
 * A loja da partida (`MinigameType.shop`). O motor faz o resto: registra o comando (`command`, padrão `comprar`; jogos podem dividir o mesmo nome),
 * manda a tabela ao navegador (o botão 🛒, a tecla da ação `shop` e o painel são do jogo base: o mod não precisa de cliente), cobra o preço, entrega os
 * itens (sem o preço ou sem espaço nada muda) e guarda o nível das melhorias de cada time. `upgrades` pede `teams`.
 */
export interface RoomShopDef { /** Nome do comando, sem barra (padrão `comprar`). */ command?: string; /** A linha do `/ajuda`. */ help?: string; /** Título do painel (padrão `🛒 Loja`). */ title?: string; /** Linha de dica sob o título. */ hint?: string; /** Título da parte das melhorias (padrão `⬆ Melhorias do time`). */ upgradesTitle?: string; offers: RoomShopOffer[]; upgrades?: RoomShopUpgrade[] }
/** `room.shop`: os níveis das melhorias de cada time nesta partida. */
export interface RoomShop {
  /** O nível da melhoria `key` do time (0 = não comprada). */
  level(team: number, key: string): number;
  /** Todos os níveis do time: `{ chave: nível }`. */
  levels(team: number): Record<string, number>;
  /** Põe o nível (0 até o máximo) e manda a loja de novo a quem do time está de pé: uma melhoria que se gasta volta a 0 e pode ser comprada outra vez. */
  setLevel(team: number, key: string, level: number): void;
  /** O preço de uma oferta, ou do nível `level` (1 = o primeiro) de uma melhoria, como a loja diz no chat: `2× Diamante`. */
  priceText(key: string, level?: number): string;
}
export interface RoomTimer { cancel(): void }
/** O loot de um baú: o nome de uma tabela registrada (`'mod:nome'`) ou uma lista `[[item, min, max, peso], ...]`. */
export type ChestLoot = string | ReadonlyArray<ReadonlyArray<string | number>>;
/** A sala de UMA partida (`e.room`): o que o motor guarda por você. Acaba junto com a partida. */
