  /** O mundo desta sala, limitado à caixa da arena. */
  readonly world: RoomWorld;
  /** Estado livre do mod para esta partida (nasce `{}`, some no fim). */
  readonly data: Record<string, any>;
  /** A fase em que a partida está (`'playing'` até o mod trocar): só o mod lê, para organizar o jogo. */
  readonly phase: string;
  setPhase(name: string): void;
  /** Milissegundos desde a largada. */
  readonly elapsed: number;
  readonly active: boolean;
