  /** Uma vez, daqui a `seconds` (0..3600; conferido a cada ~0,25 s). Todos acabam com a partida. */
  timer(seconds: number, fn: (e: { room: Room; server: ServerApi }) => void): RoomTimer;
  /** O clarão de golpe de um jogador (o piscar vermelho que todo cliente desenha) para quem está perto, sem dano nenhum. */
  flash(p: PlayerApi): void;
  /** Texto para o lobby inteiro (as linhas de resultado que todo modo diz; bots e o mundo ficam de fora). */
  announce(text: string, options?: ChatExtras): void;
  /** Protege o bloco: ninguém o quebra (nem numa sala `editable`) até `unlock`. Os baús montados em `buildArena` já nascem protegidos. */
  lock(x: number, y: number, z: number): void;
  unlock(x: number, y: number, z: number): void;
  /** O bloco está protegido (`lock`, o esqueleto de `protectBlocks`/`protectBuilt`, os baús montados)? */
  isLocked(x: number, y: number, z: number): boolean;
  /**
   * Um mob desta partida (`type`: `'zombie'` ou `'mod:chave'`) em `pos` (dentro da caixa da sala). `{ pen: true }` o prende à caixa da sala e ele nunca
   * some por distância nem queima de dia (os zumbis do Bloco da Sorte). `goal: { x, y, z, near? }`: sem jogador a até `near` blocos ele anda até lá (o Cristal da
   * Defesa); `speed` (fator), `damage` (do toque), `noPath`, `noJump`, `noKnockback`, `immortal`: o mesmo de `MobInfo.setFlags`. Os golpes nele e a morte dele chegam em
   * `onMobHit` / `onMobDeath` do jogo. O motor tira todo mob da partida quando ela acaba. Devolve o MobInfo, ou `null`.
   */
