  /** O fim de um jogo cooperativo perdido (o Cristal caiu): sem vencedor, mas conta derrota no `/stats` e no log da partida. */
  defeat(): void;
  /** Os mobs vivos que esta sala criou, cada um um MobInfo novo (posição e vida de agora). */
  readonly mobs: MobInfo[];
  /**
   * Enche o baú de `pos` (um bloco desta sala). `loot` é o nome de uma tabela de loot registrada (`'mod:nome'`, ctx.loot, espalhada em
   * espaços livres) ou uma lista `[[item, min, max, peso], ...]` (4 a 7 pilhas em espaços sorteados, a mesma conta dos baús das
   * masmorras do jogo). Quem está com o baú aberto vê na hora.
   */
  fillChest(pos: Pos, loot: ChestLoot): void;
  /** Um item no chão da arena, parado (sem arremesso) e já pegável: um gerador, um prêmio. O motor tira todo item da arena no fim. `false` fora da sala. */
  dropItem(pos: Pos, item: string, n?: number): boolean;
  /** Quantos itens (unidades, não pilhas) estão no chão a até `radius` de `pos` em cada eixo; com `item`, só daquele. */
  dropsNear(pos: Pos, radius: number, item?: string): number;
  /** A loja desta partida (`MinigameType.shop`): os níveis das melhorias dos times. `null` num jogo sem loja. */
  readonly shop: RoomShop | null;
  /** Pontos da partida; a lista vai para o log do fim se o jogo não tiver `scoreboard()`. */
