  /** O índice do time do jogador na partida (`null`: sem time). */
  teamOf(p: PlayerApi): number | null;
  /** Troca o jogador de time no meio da partida; a cor nova vai para todos da partida. O kit não muda sozinho: chame `giveKit(p)`. */
  setTeam(p: PlayerApi, team: number): void;
  /** Dá de novo, agora, o kit do jogo (`giveKit`) a quem está na partida: inventário esvaziado e vida/fome cheias (o kit de um papel novo). */
