  /** Os bots de treino da sala, quando ela declarou `bots`; `null` quando não declarou. */
  readonly bots: SoloBots | null;
  /** As estatísticas de partida da sala, quando ela declarou `stats`; `null` quando não declarou. */
  readonly stats: SoloStats | null;
  /** A linha do log de uma partida desta sala (B-367). */
  readonly log: SoloMatchLog;
  /** Os recordes da conta desta sala. */
