export interface MobHitEvent extends Cancellable { readonly mob: MobInfo; readonly attacker: PlayerApi | null; damage: number; world: WorldApi; server: ServerApi }
export interface MobHookDeathEvent { readonly mob: MobInfo; readonly killer: PlayerApi | null; drops: Drop[]; world: WorldApi; server: ServerApi }
/** Efeito de status. Ganchos só no servidor, com `e.player`, `e.level`, `e.effect` e `e.seconds`. */
