  field(path: string, desc: GasFieldDesc): FullName;
  get(name: FullName): GasDef | null;
  list(): GasDef[];
  /** A forma vertical de uma dimensão (`height`, `seaLevel`): a régua da altitude (docs/world-height.md). Nos dois lados. */
  shape(dimension: string): { height: number; seaLevel: number };
  /** Servidor: o ar em `pos` (sala ou ar livre). `exchange` soma/tira gás ali no próximo passo (quem respira). */
  sample(world: WorldApi, pos: Pos, opts?: { exchange?: Record<FullName, number> }): GasSample;
  /** Servidor: a sala em `pos` com as camadas, ou null ao ar livre. */ room(world: WorldApi, pos: Pos): GasRoom | null;
  /** Servidor, só leitura: os aglomerados fechados até `radius` blocos de `center` (os Óculos de Gás; docs/gases.md §9), o mais perto primeiro. `build` deixa montar seções novas no orçamento de fundo. */
  view(world: WorldApi, center: Pos, opts?: { radius?: number; maxNodes?: number; maxLeaves?: number; advance?: number; build?: number }): { nodes: GasViewNode[]; built: number };
  /** Servidor, só leitura: o ar LIVRE em `pos` só pelos campos (sem montar seção nem varrer coluna); `underground` diz se a célula está sob um teto. */
  outdoor(world: WorldApi, pos: Pos, underground?: boolean): { pressure: number; temperature: number; gases: Record<FullName, number> };
  /** Servidor: uma máquina põe (ou tira, negativo) gás em `pos`; false ao ar livre e enquanto o volume ali está pendente (`sample(...).pending`: tente no segundo seguinte). */ emit(world: WorldApi, pos: Pos, gas: FullName, amount: number): boolean;
  /** Servidor: um bloco mudou; as salas que tocam a célula são refeitas quando perguntadas. Com `to` (o bloco novo), as redes de dispositivos também. Devolve quantas salas. */ invalidate(dimension: string, pos: Pos, to?: FullName | null): number;
  /** Servidor: chama `fn` quando uma chama está num gás inflamável; devolva true para o gás queimar (sumir da sala). */
