  /** Servidor: anda as redes da dimensão desse mundo pelo tempo desde a última chamada (o jogo base chama a cada segundo). */ tickDevices(world: WorldApi): GasDeviceTick;
  /** Servidor: o VOLUME na posição (a alça abstrata que os dispositivos usam). */ volumeAt(world: WorldApi, x: number, y: number, z: number): GasVolume;
