  /** Os construtores de posicionamento das features (`placement` de `feature`). */
  readonly placement: PlacementBuilders;
  /** Registra uma função de densidade com nome (`<mod>:<path>`, path com "/" permitido). É passo de geração de TERRENO: região já gerada fica na era dela. */
