  /** Um campo de CLIMA: função 2D com nome que o `placement` dos biomas e o mapa leem. */
  climate(path: string, node: DensityNode, opts?: { description?: string }): string;
  /** Edita a função de densidade de qualquer um (a do jogo inclusive): `fn(inner)` devolve o nó que fica no lugar; `replace` troca inteira. */
  densityFns: {
    modify(target: FullName, fn: (inner: DensityNode) => DensityNode): string;
    replace(target: FullName, node: DensityNode): string;
  };
  /** PAISAGEM (docs/guia-de-mods.md 22.9): o desenho das ZONAS DE PAISAGEM (um por jogo: o do mod base). */
  landZoneLayout(spec: LandZoneLayoutSpec): string;
  /** Uma ZONA DE PAISAGEM (`<mod>:<path>`): nome, nicho no clima de antes das zonas, peso e os parâmetros que ela muda. Passo de terreno (eras). Não é a zona de perigo (`zone`). */
  landZone(path: string, spec: LandZoneSpec): string;
  /** Uma REDE DE RIOS (`<mod>:<path>`): água descendo um campo com nome, afluentes, lagos, deltas, cachoeiras. Passo de terreno (eras). */
  drainage(path: string, spec: DrainageSpec): string;
  /** Um tipo de MARCO (`<mod>:<path>`): zonas com peso, raio, o chão que pede e `build`. O estágio de marcos do jogo os põe (um por região). */
  landmark(path: string, spec: LandmarkSpec): string;
  /** STRUCTURES (docs/guia-de-mods.md 22.8): a STRUCTURE SET (`<mod>:<path>`): spacing, separation, footprint, salt, spread, frequency, attempts, exclusion. Data, checked now. */
  structureSet(path: string, spec: StructureSetSpec): string;
  /** A PIECE SET (`<mod>:<path>`): pieces with connectors, pools, start, maxDepth, maxRadius, gap. Data, checked now. */
  structurePieces(path: string, spec: StructurePieceSet): string;
  /** SUBSOLO (docs/guia-de-mods.md 22.7): um modelo de SALA de caverna (`<mod>:<path>`) que o terreno 2 põe nos nós do grafo de cavernas, por profundidade e bioma. Passo de terreno (eras). */
  caveRoom(path: string, spec: CaveRoomSpec): string;
  /** Decoração acrescentada às salas de qualquer um (`rooms`: nomes completos; ausente = todas): estalactites, fungos, cristais. */
  caveDecor(path: string, spec: CaveDecorSpec & { rooms?: FullName[] | null }): string;
  /** Um DEPÓSITO de minério (veio, bolsão ou camada de rocha) numa faixa de profundidade; o campo vira a função de densidade `<mod>:deposit/<path>`. */
  oreDeposit(path: string, spec: OreDepositSpec): string;
